<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reservations | Digital Library</title><link rel="stylesheet" href="/assets/app.css"></head><body><header class="site-header"><a class="brand" href="/dashboard">Digital Library</a><nav><a href="/">Catalog</a><form method="post" action="/logout"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button type="submit">Log out</button></form></nav></header><main class="container"><p class="eyebrow">Member account</p><h1>Reservations</h1><?php if ($error): ?><p class="form-error" role="alert"><?= e($error) ?></p><?php endif; ?><?php if ($success): ?><p class="form-success" role="status"><?= e($success) ?></p><?php endif; ?><?php if ($books !== []): ?><form method="post" class="book-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label for="book_id">Reserve a title</label><select id="book_id" name="book_id" required><option value="">Select a title</option><?php foreach ($books as $book): ?><option value="<?= e((string) $book['id']) ?>"><?= e($book['title']) ?></option><?php endforeach; ?></select><button type="submit">Reserve</button></form><?php endif; ?><?php if ($reservations === []): ?><div class="empty-state"><h2>No reservations</h2></div><?php else: ?><div class="book-grid"><?php foreach ($reservations as $reservation): ?><article class="book-card"><h2><?= e($reservation['title']) ?></h2><p class="muted"><?= e($reservation['status']) ?></p><?php if (in_array($reservation['status'], ['pending', 'ready'], true)): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?= e((string) $reservation['id']) ?>"><button type="submit">Cancel reservation</button></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></main></body></html>